css:
[data-bz-node="s5r1"][data-bz-node]{grid-template-columns:repeat(auto-fit, minmax(300px, 1fr))}
[data-bz-node^="s5c2-r"][data-bz-node]{border-style:solid;padding-top:clamp(24px, 3vw, 36px);padding-right:clamp(24px, 3vw, 36px);padding-bottom:clamp(24px, 3vw, 36px);padding-left:clamp(24px, 3vw, 36px);align-content:start;border-top-color:#c41230;border-right-color:#edebe3;border-bottom-color:#edebe3;border-left-color:#edebe3}
[data-bz-node^="s5h3-r"][data-bz-node] h3{font-family:Oswald, sans-serif;font-size:28px;font-weight:700;font-style:normal;line-height:1.1;letter-spacing:normal;text-transform:uppercase;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="s5t4-r"][data-bz-node] p{font-family:Inter, sans-serif;font-size:17px;font-weight:400;font-style:normal;line-height:27.2px;letter-spacing:normal;text-transform:none;text-align:start;color:rgb(20, 21, 26);margin-top:0px;margin-right:0px;margin-bottom:0px;margin-left:0px}
[data-bz-node^="s5b5-r"][data-bz-node] .bz-btn{margin:0;line-height:normal;background:transparent;border:0;border-radius:0;box-shadow:none;padding:0;display:inline-block;color:#C41230;text-decoration:underline;display:inline-block;background:rgb(196, 18, 48);color:rgb(255, 255, 255);border-top-width:2px;border-top-style:solid;border-top-color:rgb(196, 18, 48);border-right-width:2px;border-right-style:solid;border-right-color:rgb(196, 18, 48);border-bottom-width:2px;border-bottom-style:solid;border-bottom-color:rgb(196, 18, 48);border-left-width:2px;border-left-style:solid;border-left-color:rgb(196, 18, 48);text-decoration:none;font-weight:600;font-size:15px;font-family:Oswald, sans-serif;letter-spacing:0.1em;text-transform:uppercase;padding-top:16px;padding-right:28px;padding-bottom:16px;padding-left:28px}
[data-bz-node^="s5b5-r"][data-bz-node] .bz-btn:hover{background: rgb(143, 13, 33); color: rgb(255, 255, 255); border-color: rgb(143, 13, 33)}
[data-bz-node^="s5b5-r"][data-bz-node] .bz-btn:focus{outline: rgb(255, 255, 255) solid 3px; outline-offset: 3px}
[data-bz-node^="s5b5-r"][data-bz-node] .bz-btns{margin:0;gap:0}
[data-bz-node="s5"][data-bz-node]{padding-top:clamp(56px, 8vw, 100px);padding-bottom:clamp(56px, 8vw, 100px)}
